add_action( 'save_post_post', 'perfectpixel_random_posts_flush' );

// ORDER BY RAND() is slow on large sites, so pick from a cached list of recent post IDs.
function perfectpixel_random_posts_pool() {
	$ids = get_transient( 'perfectpixel_random_posts_pool' );
	if ( ! is_array( $ids ) ) {
		$ids = get_posts(
			array(
				'post_type'        => 'post',
				'post_status'      => 'publish',
				'posts_per_page'   => 200,
				'fields'           => 'ids',
				'no_found_rows'    => true,
				'suppress_filters' => false,
			)
		);
		set_transient( 'perfectpixel_random_posts_pool', $ids, HOUR_IN_SECONDS );
	}
	return $ids;
}

function perfectpixel_random_posts_flush() {
	delete_transient( 'perfectpixel_random_posts_pool' );
}

function perfectpixel_random_posts_shortcode( $atts ) {
	$atts = shortcode_atts( array( 'count' => '{{random_posts_count}}', 'title' => '' ), $atts, 'random_posts' );
	$ids  = array_diff( perfectpixel_random_posts_pool(), array( get_the_ID() ) );
	if ( ! $ids ) {
		return '';
	}
	shuffle( $ids );
	$ids  = array_slice( $ids, 0, max( 1, (int) $atts['count'] ) );
	$html = $atts['title'] ? '<h3 class="perfectpixel-random-posts-title">' . esc_html( $atts['title'] ) . '</h3>' : '';
	$html .= '<ul class="perfectpixel-random-posts">';
	foreach ( $ids as $id ) {
		$html .= '<li><a href="' . esc_url( get_permalink( $id ) ) . '">' . esc_html( get_the_title( $id ) ) . '</a></li>';
	}
	return $html . '</ul>';
}
